cmsis-pack-trace-snippet.debugvars:
// Replicator
__var REPLICATOR___INSTANCE_INDEX___ADDRESS    = 0x00000000;
__var REPLICATOR___INSTANCE_INDEX___AP         = 0x00000000;
__var REPLICATOR___INSTANCE_INDEX___ID_FILTER0 = 0x00000000; // Default: all pass to output 0
__var REPLICATOR___INSTANCE_INDEX___ID_FILTER1 = 0x00000000; // Default: all pass to output 1

sequence.block:
// Helper variables
__var savedAP    = __ap;

__ap = REPLICATOR___INSTANCE_INDEX___AP; // Set AP

Write32(REPLICATOR___INSTANCE_INDEX___ADDRESS + 0x000, REPLICATOR___INSTANCE_INDEX___ID_FILTER0);
Write32(REPLICATOR___INSTANCE_INDEX___ADDRESS + 0x004, REPLICATOR___INSTANCE_INDEX___ID_FILTER1);

__ap = savedAP;
